function read3dMeshSourceAsObjText(filePath) {
  const raw = fs13.readFileSync(filePath, "utf8");
  const low = filePath.toLowerCase();
  if (low.endsWith(".jms")) {
    return convertJmsToObjText(raw).objText;
  }
  if (low.endsWith(".dae")) {
    return convertColladaDaeToObjText(raw).objText;
  }
  return raw;
}
