  const resolveCustomTexturesDirectory = () => {
    const baseDir = process.env.PORTABLE_EXECUTABLE_DIR ? process.env.PORTABLE_EXECUTABLE_DIR : import_electron4.app.isPackaged ? path15.dirname(process.execPath) : process.cwd();
    const texturesDir = path15.join(baseDir, "textures");
    fs13.mkdirSync(texturesDir, { recursive: true });
    try {
      const existing = fs13.readdirSync(texturesDir).filter((f) => /\.(png|jpe?g|webp)$/i.test(f));
      if (existing.length === 0) {
        const presets = [
          {
            name: "unsc_olive_armor.png",
            fn: (x, y) => {
              const n = (x * 37 + y * 57 ^ x * 13) & 15;
              const seam = x % 32 === 0 || y % 32 === 0 ? -18 : 0;
              return [Math.max(0, 74 + n + seam), Math.max(0, 88 + n + seam), Math.max(0, 58 + n + seam), 255];
            }
          },
          {
            name: "covenant_hex_plate.png",
            fn: (x, y) => {
              const hx = (x + (y >> 3 & 1) * 8) % 16;
              const hy = y % 16;
              const edge = hx === 0 || hy === 0 ? 30 : 0;
              return [92 + edge, 52 + edge, 148 + edge, 255];
            }
          },
          {
            name: "forerunner_circuit_panel.png",
            fn: (x, y) => {
              const grid = x % 16 === 0 || y % 16 === 0 || (x + y) % 32 === 0;
              return grid ? [56, 189, 248, 255] : [68, 78, 92, 255];
            }
          },
          {
            name: "hazard_warning_stripes.png",
            fn: (x, y) => {
              const stripe = x + y >> 4 & 1;
              return stripe ? [234, 179, 8, 255] : [30, 32, 36, 255];
            }
          },
          {
            name: "weathered_steel_grunge.png",
            fn: (x, y) => {
              const scratch = (x * 73 + y * 19 ^ y * 29) & 31;
              const v = 110 + scratch;
              return [v, v + 2, v + 6, 255];
            }
          },
          {
            name: "desert_camo_plate.png",
            fn: (x, y) => {
              const cell = ((x >> 4) * 7 + (y >> 4) * 13 ^ (x >> 3) + (y >> 3)) & 3;
              if (cell === 0) return [194, 168, 120, 255];
              if (cell === 1) return [156, 126, 84, 255];
              if (cell === 2) return [118, 96, 66, 255];
              return [176, 148, 102, 255];
            }
          }
        ];
        for (const p of presets) {
          const rgba = new Uint8Array(64 * 64 * 4);
          for (let y = 0; y < 64; y++) {
            for (let x = 0; x < 64; x++) {
              const [r, g, b, a] = p.fn(x, y);
              const idx = (y * 64 + x) * 4;
              rgba[idx] = r;
              rgba[idx + 1] = g;
              rgba[idx + 2] = b;
              rgba[idx + 3] = a;
            }
          }
          const png = encodeRgbaToPng(rgba, 64, 64);
          fs13.writeFileSync(path15.join(texturesDir, p.name), png);
        }
      }
    } catch {
    }
    return texturesDir;
  };
  import_electron4.ipcMain.handle("bitmap:getCustomBrushTextures", async () => {
    const texturesDir = resolveCustomTexturesDirectory();
    const textures = [];
    try {
      const files = fs13.readdirSync(texturesDir).filter((f) => /\.(png|jpe?g|webp)$/i.test(f));
      for (const file of files) {
        const fullPath = path15.join(texturesDir, file);
        const ext = path15.extname(file).toLowerCase();
        const mime = ext === ".jpg" || ext === ".jpeg" ? "image/jpeg" : ext === ".webp" ? "image/webp" : "image/png";
        const buf = fs13.readFileSync(fullPath);
        const cleanName = path15.basename(file, ext).replace(/[_-]+/g, " ");
        textures.push({
          name: cleanName,
          filePath: fullPath,
          dataUrl: `data:${mime};base64,${buf.toString("base64")}`
        });
      }
    } catch {
    }
    return { ok: true, texturesDir, textures };
  });
